function n(v){const x=Number(v||0);return Number.isFinite(x)?Math.round(x):0}
function arr(v){return Array.isArray(v)?v:[]}
function stamp(v){const t=new Date(v||0).getTime();return Number.isFinite(t)?t:0}
function byNewest(a,b){return stamp(b.sortDate||b.criadoEm||b.atualizadoEm)-stamp(a.sortDate||a.criadoEm||a.atualizadoEm)}
