 if(['pago','confirmada','confirmado','concluido','concluído','concluido_saldo','aplicado','entregue'].some(x=>s.includes(x)))return 'b-green';
 if(['cancel','venc','erro','falh','descart','nao_concluido','não concluído'].some(x=>s.includes(x)))return 'b-red';
