function itemUnit(x={}){return n(x.precoUnitarioCentavos ?? x.precoCentavos ?? (n(x.totalCentavos)&&n(x.quantidade)?Math.round(n(x.totalCentavos)/Math.max(1,n(x.quantidade))):0))}
function itemQty(x={}){return Math.max(1,n(x.quantidade||x.quantity||1))}
function itemTotal(x={}){return n(x.totalCentavos||itemUnit(x)*itemQty(x))}
function itemName(x={}){return x.nome||x.description||x.produto||'Item'}
function itemMeta(x={}){const m=x.metadados||{},schedule=x.tipo==='programacao_lanche'||x.tipoOperacional==='programacao_lanche'?`${m.quantidadeEntregas||x.pedido?.itens?.length||0} entrega(s)${m.primeiraData?` · ${m.primeiraData}${m.ultimaData&&m.ultimaData!==m.primeiraData?` a ${m.ultimaData}`:''}`:''}`:'';return [x.categoria,x.tamanho||m.tamanho,x.modelo||m.modelo,m.competencia,x.competencia,m.referencia,x.referencia,schedule].filter(Boolean).join(' · ')}
function itemLinesHtml(lines=[],empty='Sem composição detalhada registrada.'){
 if(!arr(lines).length)return `<div class="empty-soft">${esc(empty)}</div>`;
 return `<div class="v162-item-list">${arr(lines).map(x=>`<div class="v162-item-line"><div><strong>${esc(itemName(x))}</strong><div class="muted">${itemQty(x)} × ${fmt(itemUnit(x))}${itemMeta(x)?` · ${esc(itemMeta(x))}`:''}</div></div><strong>${fmt(itemTotal(x))}</strong></div>`).join('')}</div>`;
}
function operationTitle(op){return ({venda_catalogo:'Produtos e serviços',venda_imediata:'Produtos e serviços',pedido_cantina_programado:'Programação de lanches',adicionar_credito:'Adicionar crédito',regularizar_debito:'Regularização de saldo'}[op]||prettify(op||'Venda'))}
