/* VENDAS: histórico unificado */
async function buildSalesRowsV162(){
 await (window.ensureStudentsLoadedV218?.()||Promise.resolve());const [ss,ls,cs]=await Promise.all([db.collection('vendas').orderBy('criadoEm','desc').limit(150).get().catch(()=>db.collection('vendas').limit(150).get()),db.collection('vendas_online_links').orderBy('atualizadoEm','desc').limit(120).get().catch(()=>db.collection('vendas_online_links').limit(120).get()),db.collection('pagamentos_checkout').orderBy('atualizadoEm','desc').limit(120).get().catch(()=>db.collection('pagamentos_checkout').limit(120).get())]);const sales=ss.docs.map(d=>({id:d.id,...d.data()})),links=ls.docs.map(d=>({id:d.id,...d.data()})),checkouts=cs.docs.map(d=>({id:d.id,...d.data()}));
 const saleById=new Map(sales.map(s=>[s.id,s])),checkoutByNsu=new Map(checkouts.map(c=>[c.orderNsu||c.id,c])),usedSales=new Set(),usedCheckouts=new Set(),rows=[];
 for(const l of links){const sale=l.vendaId?saleById.get(l.vendaId):null,c=l.orderNsu?checkoutByNsu.get(l.orderNsu):null;if(sale)usedSales.add(sale.id);if(c)usedCheckouts.add(c.orderNsu||c.id);const status=sale?'confirmada':(c?checkoutOperationalStatusV218(c,l.status||'link_gerado'):(l.status||'link_gerado'));rows.push({key:`online:${l.id}`,channel:'online',link:l,sale,checkout:c,status,alunoId:l.alunoId||sale?.alunoId||c?.alunoId,alunoNome:l.alunoNome||sale?.alunoNome||c?.alunoNome,operacao:l.operacao||c?.tipo||'venda_catalogo',totalCentavos:n(sale?.valorBrutoCentavos||l.totalCentavos||c?.pedidoTotalCentavos||c?.totalCentavos),lines:sale?.itens||l.itens||c?.payloadOperacional?.itens||[],orderNsu:l.orderNsu||c?.orderNsu||c?.id||'',sortDate:l.pagoEm||sale?.criadoEm||l.atualizadoEm||l.criadoEm});}
 for(const s of sales){if(usedSales.has(s.id))continue;const online=String(s.origem||'').includes('online')||String(s.formaPagamento||'').includes('checkout');const c=s.orderNsu?checkoutByNsu.get(s.orderNsu):null;if(c)usedCheckouts.add(c.orderNsu||c.id);rows.push({key:`sale:${s.id}`,channel:online?'online':'presencial',sale:s,checkout:c,status:s.status||'confirmada',alunoId:s.alunoId,alunoNome:s.alunoNome,operacao:'venda_catalogo',totalCentavos:n(s.valorBrutoCentavos),lines:s.itens||[],orderNsu:s.orderNsu||c?.orderNsu||'',sortDate:s.criadoEm});}
 for(const c of checkouts){const nsu=c.orderNsu||c.id;if(usedCheckouts.has(nsu))continue;if(!STAFF_PROFILES.has(c.criadoPorPerfil))continue;rows.push({key:`checkout:${nsu}`,channel:'online',checkout:c,status:checkoutOperationalStatusV218(c,'aguardando_pagamento'),alunoId:c.alunoId,alunoNome:c.alunoNome,operacao:c.tipo,totalCentavos:n(c.pedidoTotalCentavos||c.totalCentavos),lines:c.payloadOperacional?.itens||[],orderNsu:nsu,sortDate:c.pagamentoConfirmadoEm||c.atualizadoEm||c.criadoEm});}
 return rows.sort(byNewest);
}
function salesMatchesV162(r,f){if(f==='todos')return true;if(f==='presencial'||f==='online')return r.channel===f;if(f==='pendentes')return !paidStatus(r.status)&&!r.sale&&activeOnline(r.status);if(f==='concluidas')return Boolean(r.sale)||paidStatus(r.status);return true}
function saleStatusTextV162(r){if(r.sale)return 'Concluída';if(paidStatus(r.status))return r.status==='pago_revisao'?'Paga — revisar':'Paga';if(activeOnline(r.status))return onlineLabel(r.status);return prettify(r.status)}
function saleActionsV162(r){
 if(r.link&&activeOnline(r.status)){const c=r.checkout||{};return `<button class="btn btn-primary" onclick="openUnifiedSaleLinkV162('${safeJs(r.key)}')">Abrir</button><button class="btn btn-outline" onclick="copyUnifiedSaleLinkV162('${safeJs(r.key)}')">Copiar link</button>${r.orderNsu?`<button class="btn btn-light" onclick="syncInfinitePayV218('${safeJs(r.orderNsu)}','${safeJs(c.transactionNsu||'')}','${safeJs(c.invoiceSlug||'')}')">Sincronizar</button><button class="btn btn-orange" onclick="openManualReconciliationV218('${safeJs(r.orderNsu)}')">Confirmar recebimento</button>`:''}<button class="btn btn-light" onclick="renewOnlineLinkV158('${safeJs(r.link.id)}')">Novo link</button><button class="btn btn-red" onclick="cancelOnlineLinkV158('${safeJs(r.link.id)}')">Cancelar</button>`;}
 return `<button class="btn btn-primary" onclick="openUnifiedSaleDetailV162('${safeJs(r.key)}')">Detalhar</button>${r.sale||r.orderNsu?`<button class="btn btn-green" onclick="openSaleReceiptsV162('${safeJs(r.key)}')">Comprovantes</button>`:''}`;
}
function salesRowHtmlV162(r){const title=operationTitle(r.operacao),preview=arr(r.lines).slice(0,3).map(x=>itemName(x)).join(' + '),a=r.alunoId?student(r.alunoId):{},turma=r.sale?.turma||r.link?.turma||r.checkout?.turma||a.turma||'';return `<div class="v162-op-row"><div class="v162-op-main"><div class="v162-op-title"><strong>${r.alunoId?`<button class="v165-link" onclick="openSystemEntityV165('aluno','${safeJs(r.alunoId)}')">${esc(r.alunoNome||a.nome||'Aluno')}</button>`:esc(r.alunoNome||a.nome||'Aluno')}</strong><span class="badge ${statusClass(r.status)}">${esc(saleStatusTextV162(r))}</span><span class="badge b-blue">${r.channel==='online'?'Online':'Presencial'}</span></div><div class="muted">${esc(turma||'Turma não informada')}${r.sortDate?` · ${humanDate(r.sortDate)}`:''}${r.sale?.operadorNome?` · ${esc(r.sale.operadorNome)}`:r.link?.criadoPorNome?` · ${esc(r.link.criadoPorNome)}`:''}</div><div class="v162-op-desc"><strong>${esc(title)}</strong>${preview?`<span>${esc(preview)}${r.lines.length>3?'…':''}</span>`:''}</div></div><div class="v162-op-value"><strong>${fmt(r.totalCentavos)}</strong><div class="actions">${saleActionsV162(r)}</div></div></div>`}
async function renderVendasV162(filter){state.v162CurrentView='vendas';filter=filter||state.v162SalesFilter||'todos';state.v162SalesFilter=filter;const el=setLoading('Vendas da secretaria','Venda presencial e online em um só histórico.');const rows=await buildSalesRowsV162();state.v162SalesRows=rows;state.v158OnlineRows=rows.filter(x=>x.link).map(x=>x.link);const shown=rows.filter(r=>salesMatchesV162(r,filter));const filters=[['todos','Todas'],['presencial','Presenciais'],['online','Online'],['pendentes','Pendentes'],['concluidas','Concluídas']];el.innerHTML=pageHeader('Vendas da secretaria','Registre uma nova venda e acompanhe todas as operações.')+`<div class="v158-sale-channel-grid"><button class="v158-channel-card" onclick="startUnifiedSaleV160('presencial')"><span class="v158-channel-icon">🏫</span><strong>Venda presencial</strong><small>Dinheiro, Pix, cartão ou saldo do aluno.</small></button><button class="v158-channel-card" onclick="startUnifiedSaleV160('online')"><span class="v158-channel-icon">🔗</span><strong>Venda online</strong><small>Gere um link vinculado ao aluno e à compra.</small></button></div><div class="card" style="margin-top:15px"><div class="card-head v162-history-head"><div><div class="card-title">Histórico de vendas</div><div class="muted">Todos os canais · mais recentes primeiro</div></div><button class="btn btn-light" onclick="renderVendasV162('${filter}')">Atualizar</button></div><div class="v162-filter-tabs">${filters.map(([id,label])=>`<button class="btn ${filter===id?'btn-primary':'btn-light'}" onclick="renderVendasV162('${id}')">${label}</button>`).join('')}</div><div class="card-body">${shown.length?`<div class="v162-op-list">${shown.map(salesRowHtmlV162).join('')}</div>`:'<div class="empty">Nenhuma venda neste filtro.</div>'}</div></div>`}
function findSaleRowV162(key){return arr(state.v162SalesRows).find(x=>x.key===key)}
function openUnifiedSaleLinkV162(key){const r=findSaleRowV162(key),url=r?.link?.urlInterna||r?.checkout?.checkoutUrl;if(!url)return appMessage('Link indisponível.');window.open(url,'_blank','noopener')}
