async function openUnifiedSaleDetailV162(key){const r=findSaleRowV162(key);if(!r)return;const pays=arr(r.sale?.pagamentos),payHtml=pays.length?`<div class="card-title" style="margin:16px 0 8px">Formas de pagamento</div>${pays.map(p=>`<div class="v162-item-line"><div><strong>${esc(prettify(p.metodo))}</strong><div class="muted">${p.metodo==='cartao'?`Líquido recebido ${fmt(p.valorLiquidoCentavos||p.valorAplicadoCentavos)} · bruto cobrado ${fmt(p.valorBrutoPassadoCentavos||p.valorAplicadoCentavos)} · taxa ${fmt(p.taxaCentavos)}${p.parcelas?` · ${p.parcelas}x`:''}`:p.metodo==='dinheiro'?`Recebido ${fmt(p.valorRecebidoCentavos||p.valorAplicadoCentavos)} · troco ${fmt(p.trocoCentavos)}`:p.referencia?`Referência ${esc(p.referencia)}`:''}</div></div><strong>${fmt(p.valorAplicadoCentavos)}</strong></div>`).join('')}`:'';openModal('Detalhes da venda',`<div class="v162-detail-hero"><div><small>${r.channel==='online'?'Venda online':'Venda presencial'}</small><strong>${r.alunoId?`<button class="v165-link" onclick="openSystemEntityV165('aluno','${safeJs(r.alunoId)}')">${esc(r.alunoNome||student(r.alunoId).nome||'Aluno')}</button>`:esc(r.alunoNome||student(r.alunoId).nome||'Aluno')}</strong><span>${r.sortDate?humanDate(r.sortDate):''}</span></div><span class="badge ${statusClass(r.status)}">${esc(saleStatusTextV162(r))}</span></div>${paymentSummaryHtmlV162(r)}<div class="card-title" style="margin:16px 0 8px">Itens e valores</div>${itemLinesHtml(r.lines)}${payHtml}<div class="actions" style="margin-top:16px">${r.sale||r.orderNsu?`<button class="btn btn-green" onclick="openSaleReceiptsV162('${safeJs(r.key)}')">Comprovantes</button>`:''}${r.alunoId?`<button class="btn btn-outline" onclick="openStudentDetails('${safeJs(r.alunoId)}')">Abrir conta do aluno</button>`:''}</div>`)}
function openSaleReceiptsV162(key){const r=findSaleRowV162(key);if(!r)return;openModal('Comprovantes',`<div class="v156-receipt-options">${r.orderNsu?`<button class="v156-receipt-option" onclick="openReceiptV142('${safeJs(r.orderNsu)}')"><span>Pagamento</span><strong>Abrir comprovante completo</strong></button>`:''}${r.sale?.id?`<button class="v156-receipt-option" onclick="downloadSaleReceiptPdfV110('${safeJs(r.sale.id)}')"><span>Escola Piaget</span><strong>Comprovante da venda em PDF</strong></button>`:''}</div>${!r.orderNsu&&!r.sale?.id?'<div class="empty">Nenhum comprovante disponível para esta operação.</div>':''}`)}


