/* DETALHAMENTO DE MOVIMENTAÇÃO — compartilhado */
async function fetchMovementBundleV162(id){const snap=await db.collection('movimentos_conta').doc(id).get();if(!snap.exists)throw new Error('Movimentação não encontrada.');const movement={id:snap.id,...snap.data()};let sale=null;if(movement.vendaId){const s=await db.collection('vendas').doc(movement.vendaId).get().catch(()=>null);if(s?.exists)sale={id:s.id,...s.data()}}return{movement,sale}}
function movementSignedV162(m){const raw=n(m.valorCentavos);if(raw<0)return raw;if(['compra','consumo','saida'].includes(m.tipo))return -Math.abs(raw);return raw}
function movementTitleV162(m){try{return movementLabelV151(m)}catch(e){try{return movementTypeLabelV143(m)}catch(_){return prettify(m.subtipo||m.tipo)}}}
async function openMovementDetailV162(id,mode='staff'){openModal('Detalhes da movimentação','<div class="v151-inline-loader">Carregando detalhes...</div>');try{const {movement:m,sale}=await fetchMovementBundleV162(id),lines=arr(m.itens).length?m.itens:(sale?.itens||[]),value=movementSignedV162(m),orderNsu=m.orderNsu||sale?.orderNsu||'';state.v162MovementDetail={movement:m,sale};$('#modalBody').innerHTML=`<div class="v162-detail-hero"><div><small>Movimentação</small><strong>${esc(movementTitleV162(m))}</strong><span>${humanDate(m.criadoEm)}</span></div><strong class="${value>=0?'v162-positive':'v162-negative'}">${value>=0?'+':''}${fmt(value)}</strong></div><div class="v162-detail-grid"><div><small>Valor global</small><strong>${value>=0?'+':''}${fmt(value)}</strong></div><div><small>Saldo após</small><strong>${m.saldoDepoisCentavos!==undefined?(m.saldoDepoisCentavos>=0?'+':'')+fmt(m.saldoDepoisCentavos):'-'}</strong></div><div><small>Forma</small><strong>${esc(prettify(m.formaPagamento||m.origem||'-'))}</strong></div><div><small>Origem</small><strong>${esc(prettify(m.subtipo||m.tipo||'-'))}</strong></div><div><small>Venda</small><strong>${esc(m.vendaId||'-')}</strong></div><div><small>NSU</small><strong>${esc(orderNsu||'-')}</strong></div></div><div class="card-title" style="margin:16px 0 8px">Composição da operação</div>${itemLinesHtml(lines,'Esta movimentação não possui itens individuais.')}<div class="actions" style="margin-top:16px">${orderNsu?(mode==='parent'?`<button class="btn btn-green" onclick="openParentReceiptMenuV156('${safeJs(m.id)}','${safeJs(orderNsu)}')">Comprovante</button>`:`<button class="btn btn-green" onclick="openReceiptV142('${safeJs(orderNsu)}')">Comprovante</button>`):''}${sale?.id?`<button class="btn btn-primary" onclick="downloadSaleReceiptPdfV110('${safeJs(sale.id)}')">Venda em PDF</button>`:''}</div>`}catch(e){$('#modalBody').innerHTML=`<div class="alert danger">${esc(e.message)}</div>`}}

/* PORTAL: apenas acrescenta detalhamento, preservando experiência */
async function openParentMovementsV162(){const a=state.parentStudent;openModal('Movimentações da conta','<div class="v151-inline-loader">Carregando movimentações...</div>');try{const [ms,cs]=await Promise.all([db.collection('movimentos_conta').where('alunoId','==',a.id).limit(200).get(),db.collection('pagamentos_checkout').where('alunoId','==',a.id).limit(80).get().catch(()=>({docs:[]}))]);const rows=ms.docs.map(d=>({id:d.id,...d.data()})).sort(byNewest),checkouts=cs.docs.map(d=>({id:d.id,...d.data()}));state.v162ParentMoves=rows;$('#modalBody').innerHTML=rows.length?`<div class="v151-list">${rows.map(m=>{const v=movementSignedV162(m),checkout=checkouts.find(c=>(m.orderNsu&&(c.orderNsu||c.id)===m.orderNsu)||(m.pedidoId&&c.pedidoId===m.pedidoId)),orderNsu=m.orderNsu||checkout?.orderNsu||checkout?.id||'',lines=arr(m.itens),preview=lines.slice(0,2).map(x=>`${itemQty(x)}× ${itemName(x)} — ${fmt(itemTotal(x))}`).join(' · ');return `<div class="v151-ledger-card v162-parent-ledger"><div><strong>${humanDate(m.criadoEm)}</strong><div class="muted" style="font-size:11px">${esc(prettify(m.formaPagamento||m.origem||'-'))}</div></div><div><strong>${esc(movementTitleV162(m))}</strong><div class="muted" style="font-size:12px;margin-top:3px">${preview?esc(preview):(m.descricao?esc(m.descricao):'Valor global da movimentação')}</div>${m.saldoDepoisCentavos!==undefined?`<div class="muted" style="font-size:11px;margin-top:4px">Saldo após: ${m.saldoDepoisCentavos>=0?'+':''}${fmt(m.saldoDepoisCentavos)}</div>`:''}<div class="actions" style="margin-top:7px"><button class="btn btn-light" onclick="openMovementDetailV162('${safeJs(m.id)}','parent')">Detalhar</button>${orderNsu?`<button class="btn btn-outline" onclick="openParentReceiptMenuV156('${safeJs(m.id)}','${safeJs(orderNsu)}')">Comprovante</button>`:''}</div></div><div class="amount ${v>=0?'in':'out'}">${v>=0?'+':''}${fmt(v)}</div></div>`}).join('')}</div>`:'<div class="empty">Nenhuma movimentação registrada.</div>'}catch(e){$('#modalBody').innerHTML=`<div class="alert danger">${esc(e.message)}</div>`}}

/* CONTA ADMINISTRATIVA DO ALUNO */
async function openStudentDetailsV162(id){const a=student(id);openModal('Conta do aluno','<div class="v151-inline-loader">Carregando visão completa...</div>');try{const [acc,ms,ps,fs,os,ls,cs,vs]=await Promise.all([getAccount(id),db.collection('movimentos_conta').where('alunoId','==',id).limit(200).get().catch(()=>({docs:[]})),db.collection('pedidos').where('alunoId','==',id).limit(120).get().catch(()=>({docs:[]})),db.collection('pedidos_farda').where('alunoId','==',id).limit(80).get().catch(()=>({docs:[]})),db.collection('ocorrencias_entrega').where('alunoId','==',id).limit(250).get().catch(()=>({docs:[]})),db.collection('vendas_online_links').where('alunoId','==',id).limit(80).get().catch(()=>({docs:[]})),db.collection('pagamentos_checkout').where('alunoId','==',id).limit(80).get().catch(()=>({docs:[]})),db.collection('vendas').where('alunoId','==',id).limit(120).get().catch(()=>({docs:[]}))]);const data={id,student:a,account:acc,moves:ms.docs.map(d=>({id:d.id,...d.data()})).sort(byNewest),orders:ps.docs.map(d=>({id:d.id,...d.data(),tipoPedido:'cantina'})).sort(byNewest),uniforms:fs.docs.map(d=>({id:d.id,...d.data(),tipoPedido:'farda'})).sort(byNewest),occurrences:os.docs.map(d=>({id:d.id,...d.data()})).sort((x,y)=>String(x.dataChave||'').localeCompare(String(y.dataChave||''))),links:ls.docs.map(d=>({id:d.id,...d.data()})).sort(byNewest),checkouts:cs.docs.map(d=>({id:d.id,...d.data()})).sort(byNewest),sales:vs.docs.map(d=>({id:d.id,...d.data()})).sort(byNewest)};state.v162StudentAccount=data;$('#modalBody').innerHTML=`<div class="v162-student-head"><div><span>${esc(a.turma||'-')} · Matrícula ${esc(a.matricula||'-')}</span><strong>${esc(a.nome||id)}</strong><small>Responsável: ${esc(a.responsavelFinanceiro||'-')}</small></div><span class="badge ${isBlocked(acc)?'b-red':'b-green'}">${isBlocked(acc)?'Conta bloqueada':'Conta liberada'}</span></div><div class="v162-student-tabs"><button onclick="renderStudentAccountTabV162('resumo')">Resumo</button><button onclick="renderStudentAccountTabV162('lanches')">Lanches</button><button onclick="renderStudentAccountTabV162('pedidos')">Pedidos</button><button onclick="renderStudentAccountTabV162('movimentos')">Movimentações</button><button onclick="renderStudentAccountTabV162('pagamentos')">Pagamentos</button></div><div id="v162StudentAccountBody"></div>`;document.querySelector('.modal')?.classList.add('v162-modal-wide');renderStudentAccountTabV162('resumo')}catch(e){$('#modalBody').innerHTML=`<div class="alert danger">${esc(e.message)}</div>`}}
function studentBalanceHtmlV162(d){const net=accountNet(d.account);return `<div class="v162-balance-grid"><div><small>Saldo da conta</small><strong class="${net>=0?'v162-positive':'v162-negative'}">${net>=0?'+':''}${fmt(net)}</strong></div><div><small>Crédito disponível</small><strong>${fmt(Math.max(0,net))}</strong></div><div><small>Saldo em aberto</small><strong>${fmt(Math.max(0,-net))}</strong></div><div><small>Limite</small><strong>${fmt(d.account.limiteFiadoCentavos||0)}</strong></div></div>`}
function occurrenceCardV162(o){return `<div class="v162-mini-card"><div><strong>${esc(o.dataChave||'-')}</strong><span>${arr(o.itens).map(x=>`${itemQty(x)}× ${itemName(x)}`).join(', ')||'Lanche programado'}</span></div><span class="badge ${statusClass(o.status)}">${esc(prettify(o.status||'programado'))}</span></div>`}
function orderCardV162(o){const isUniform=o.tipoPedido==='farda',status=isUniform?(o.statusAtendimento||o.statusPagamento):(o.statusPedido||o.statusPagamento),title=isUniform?(o.produto||'Fardamento'):(o.modalidade==='mensal'?'Lanches do mês':o.modalidade==='semanal'?'Lanches da semana':'Pedido de cantina');return `<div class="v162-mini-card"><div><strong>${esc(title)}</strong><span>${humanDate(o.criadoEm)} · ${fmt(o.totalCentavos||0)}</span></div><div><span class="badge ${statusClass(status)}">${esc(prettify(status))}</span><button class="btn btn-light" onclick="openAdminOrderDetailV162('${isUniform?'farda':'cantina'}','${safeJs(o.id)}')">Detalhar</button></div></div>`}
function movementCardsV162(moves,limit=999){return arr(moves).slice(0,limit).map(m=>{const v=movementSignedV162(m);return `<div class="v162-mini-card"><div><strong>${esc(movementTitleV162(m))}</strong><span>${humanDate(m.criadoEm)} · ${v>=0?'+':''}${fmt(v)}</span></div><button class="btn btn-light" onclick="openMovementDetailV162('${safeJs(m.id)}','staff')">Detalhar</button></div>`}).join('')||'<div class="empty-soft">Nenhuma movimentação.</div>'}
function paymentCardsV162(d,limit=999){const rows=[...d.links.map(l=>({kind:'link',id:l.id,status:l.status,total:n(l.totalCentavos),sortDate:l.pagoEm||l.criadoEm,orderNsu:l.orderNsu||'',raw:l})),...d.checkouts.filter(c=>!d.links.some(l=>l.orderNsu&&(l.orderNsu===(c.orderNsu||c.id)))).map(c=>({kind:'checkout',id:c.id,status:c.statusAplicacao==='aplicado'?'pago':c.status,total:n(c.pedidoTotalCentavos||c.totalCentavos),date:c.pagamentoConfirmadoEm||c.criadoEm,orderNsu:c.orderNsu||c.id,raw:c}))].sort(byNewest).slice(0,limit);state.v162StudentPayments=rows;return rows.map((p,i)=>`<div class="v162-mini-card"><div><strong>${esc(operationTitle(p.raw.operacao||p.raw.tipo))}</strong><span>${humanDate(p.sortDate)} · ${fmt(p.total)}</span></div><div><span class="badge ${statusClass(p.status)}">${esc(p.kind==='link'?onlineLabel(p.status):checkoutLabel(p.status))}</span>${p.orderNsu&&paidStatus(p.status)?`<button class="btn btn-green" onclick="openReceiptV142('${safeJs(p.orderNsu)}')">Comprovante</button>`:''}</div></div>`).join('')||'<div class="empty-soft">Nenhum pagamento.</div>'}
function renderStudentAccountTabV162(tab='resumo'){const d=state.v162StudentAccount,h=$('#v162StudentAccountBody');if(!d||!h)return;document.querySelectorAll('.v162-student-tabs button').forEach(b=>b.classList.toggle('active',b.textContent.toLowerCase().startsWith(tab==='movimentos'?'movimenta':tab)));const today=dateKey(),future=d.occurrences.filter(o=>String(o.dataChave||'')>=today&&!['cancelado','entregue','ausente','aluno_ausente','nao_entregue'].includes(o.status)),openOrders=[...d.orders,...d.uniforms].filter(o=>!['concluido','entregue','cancelado','nao_concluido'].includes(String(o.statusPedido||o.statusAtendimento||o.statusPagamento||''))),pending=d.links.filter(l=>activeOnline(l.status));if(tab==='resumo'){h.innerHTML=`${studentBalanceHtmlV162(d)}<div class="actions v162-student-actions"><button class="btn btn-primary" onclick="openAccountPaymentV141('${safeJs(d.id)}','staff')">Gerar cobrança</button><button class="btn btn-green" onclick="registerManualPaymentV141('${safeJs(d.id)}')">Registrar pagamento</button><button class="btn btn-outline" onclick="toggleManualBlock('${safeJs(d.id)}',${!d.account.bloqueioManual})">${d.account.bloqueioManual?'Remover bloqueio':'Bloquear conta'}</button><button class="btn btn-light" onclick="generateReport('${safeJs(d.id)}')">Relatório</button></div><div class="v162-overview-grid"><section><div class="card-title">Próximos lanches</div>${future.slice(0,4).map(occurrenceCardV162).join('')||'<div class="empty-soft">Nenhum lanche programado.</div>'}</section><section><div class="card-title">Pedidos em aberto</div>${openOrders.slice(0,4).map(orderCardV162).join('')||'<div class="empty-soft">Nenhum pedido em aberto.</div>'}</section><section><div class="card-title">Links pendentes</div>${pending.slice(0,4).map(l=>`<div class="v162-mini-card"><div><strong>${esc(operationTitle(l.operacao))}</strong><span>${fmt(l.totalCentavos||0)}</span></div><button class="btn btn-light" onclick="window.open('${safeJs(l.urlInterna||'#')}','_blank')">Abrir</button></div>`).join('')||'<div class="empty-soft">Nenhum link pendente.</div>'}</section><section><div class="card-title">Movimentações recentes</div>${movementCardsV162(d.moves,4)}</section></div>`;return}if(tab==='lanches'){h.innerHTML=`<div class="card-title">Lanches programados e entregas</div>${d.occurrences.length?d.occurrences.map(occurrenceCardV162).join(''):'<div class="empty">Nenhum lanche programado.</div>'}`;return}if(tab==='pedidos'){h.innerHTML=`<div class="card-title">Pedidos do aluno</div>${[...d.orders,...d.uniforms].sort(byNewest).map(orderCardV162).join('')||'<div class="empty">Nenhum pedido.</div>'}`;return}if(tab==='movimentos'){h.innerHTML=`<div class="card-title">Extrato e composição</div>${movementCardsV162(d.moves)}`;return}h.innerHTML=`<div class="card-title">Links, pagamentos e comprovantes</div>${paymentCardsV162(d)}`}
async function openAdminOrderDetailV162(type,id){openModal('Detalhes do pedido','<div class="v151-inline-loader">Carregando...</div>');try{const collection=type==='farda'?'pedidos_farda':'pedidos',s=await db.collection(collection).doc(id).get();if(!s.exists)throw new Error('Pedido não encontrado.');const o={id:s.id,...s.data()};let lines=[];if(type==='farda')lines=[{nome:o.produto||'Fardamento',quantidade:o.quantidade||1,precoUnitarioCentavos:o.precoUnitarioCentavos,totalCentavos:o.totalCentavos,tamanho:o.tamanho,modelo:o.modelo}];else lines=arr(o.dias).flatMap(d=>arr(d.itens).map(x=>({...x,dataChave:d.dataChave})));$('#modalBody').innerHTML=`<div class="v162-detail-hero"><div><small>Pedido</small><strong>${esc(type==='farda'?'Fardamento':'Cantina')}</strong><span>${humanDate(o.criadoEm)}</span></div><strong>${fmt(o.totalCentavos||0)}</strong></div><div class="v162-detail-grid">${o.alunoId?`<div><small>Aluno</small><strong><button class="v165-link" onclick="openSystemEntityV165('aluno','${safeJs(o.alunoId)}')">${esc(o.alunoNome||student(o.alunoId).nome||'Abrir aluno')}</button></strong><span>${esc(o.turma||student(o.alunoId).turma||'')}</span></div>`:''}<div><small>Pagamento</small><strong>${esc(prettify(o.statusPagamento||'-'))}</strong></div><div><small>Atendimento</small><strong>${esc(prettify(o.statusAtendimento||o.statusPedido||'-'))}</strong></div><div><small>Modalidade</small><strong>${esc(prettify(o.modalidade||type))}</strong></div><div><small>Pedido</small><strong>${esc(o.id)}</strong></div></div><div class="card-title" style="margin:16px 0 8px">Composição</div>${itemLinesHtml(lines)}`;document.querySelector('.modal')?.classList.add('v162-modal-wide')}catch(e){$('#modalBody').innerHTML=`<div class="alert danger">${esc(e.message)}</div>`}}

